DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.load_demo(boolean)'::regprocedure) INTO definition; definition:=replace(definition,'ARRAY[1400,2200,3400,4200,5100,6200,7300,8800,9600,12600]','ARRAY[1400,2200,3400,4200,5100,6200,7300,8800,9600,12800]'); definition:=replace(definition,'AND amount_cents=12600','AND amount_cents=12800'); EXECUTE definition; END $$;